-- STEP 1: query [kommuner]
SELECT kommunenummer, ST_AsGeoJSON(ST_Transform(omrade,4326)) AS geom_geojson, ST_XMin(ST_Transform(omrade,4326)) AS minx, ST_YMin(ST_Transform(omrade,4326)) AS miny, ST_XMax(ST_Transform(omrade,4326)) AS maxx, ST_YMax(ST_Transform(omrade,4326)) AS maxy FROM kommuner_627ee106072240e99d2b21ec4717bf01.kommune WHERE lower(kommunenavn) = 'bergen';

-- STEP BOUNDARY --

-- STEP 2: query [matrikkeleneiendomskartteig]
SELECT teigid, kommunenummer, matrikkelnummertekst, ST_AsGeoJSON(ST_Transform(omrade,4326)) AS geom_geojson FROM matrikkeleneiendomskartteig_36313fab8faa42d99cb779d86d1ca26d.teig WHERE kommunenummer = '4601';

-- STEP BOUNDARY --

-- STEP 3: query [stormflohavniva]
